import Template from "./template";
import paper from "paper";
import { DEFAULT_CHANNEL_WIDTH_UM } from "./channelWidths";
import { contiguousCenterlines, squareChannelOutline } from "./channelJoin";

export default class Connection extends Template {
    constructor() {
        super();
    }

    __setupDefinitions(): void  {
        this.__unique = {
            start: "Point",
            end: "Point",
            wayPoints: "PointArray",
            segments: "SegmentArray"
        };

        this.__heritable = {
            connectionSpacing: "Float",
            channelWidth: "Float",
            depth: "Float",
            /** 0 = rectangular (square) channel profile with flat ends; 1 = rounded profile (stadium outline, circular cross-section). */
            crossSection: "Float"
        };

        this.__defaults = {
            connectionSpacing: 1600,
            channelWidth: DEFAULT_CHANNEL_WIDTH_UM,
            depth: 250,
            crossSection: 0
        };

        this.__units = {
            connectionSpacing: "μm",
            channelWidth: "μm",
            depth: "μm",
            crossSection: ""
        };

        this.__minimum = {
            connectionSpacing: 0,
            channelWidth: 3,
            depth: 10,
            crossSection: 0
        };

        this.__maximum = {
            connectionSpacing: 10000,
            channelWidth: 12000,
            depth: 1200,
            crossSection: 1
        };

        this.__featureParams = {
            connectionSpacing: "connectionSpacing",
            start: "start",
            end: "end",
            wayPoints: "wayPoints",
            channelWidth: "channelWidth",
            segments: "segments",
            depth: "depth",
            crossSection: "crossSection"
        };

        this.__targetParams = {
            connectionSpacing: "connectionSpacing",
            wayPoints: "wayPoints",
            channelWidth: "channelWidth",
            segments: "segments",
            depth: "depth",
            crossSection: "crossSection"
        };

        this.__placementTool = "ConnectionTool";

        this.__toolParams = {
            start: "start",
            end: "end"
        };

        this.__renderKeys = ["FLOW"];

        this.__mint = "CHANNEL";

        this.__zOffsetKeys = {
            FLOW: "depth"
        };

        this.__substrateOffset = {
            FLOW: "0"
        };
    }

    render2D(params: { [k: string]: any }, key: string) {
        const start = params.start;
        const end = params.end;
        const color = params.color;
        const wayPoints = params.wayPoints;
        const channelWidth = Number(params.channelWidth || params.width) || DEFAULT_CHANNEL_WIDTH_UM;
        const segments = params.segments;
        const connectionpath = new paper.CompoundPath("");
        // Set winding before adding children. Default even-odd punches a hole
        // wherever two rounded end-caps meet (mux 90° corners, shared trunks).
        connectionpath.fillRule = "nonzero";
        let startpoint, endpoint;

        let p1, p2;

        const crossSection = params.crossSection !== undefined && params.crossSection !== null ? Number(params.crossSection) : 0;
        const roundedProfile = crossSection >= 0.5;

        if (!Array.isArray(segments) || segments.length === 0) {
            console.warn("[3DuF] Connection render skipped: missing segments", params);
            connectionpath.fillColor = color;
            return connectionpath;
        }

        if (!roundedProfile) {
            // One outline per contiguous run. 90° corners stay sharp; other
            // bends fillet at half the channel width. Valve gaps stay open
            // because those runs do not share an endpoint.
            this.__drawSquareChannelRuns(connectionpath, segments, channelWidth);
        } else {
            const capAt = this.__roundedCapLookup(segments, wayPoints);

            for (const i in segments) {
                const segment = segments[i];
                if (!segment || segment.length < 2 || !segment[0] || !segment[1]) {
                    console.warn("[3DuF] Connection render skipped a malformed segment", segment);
                    continue;
                }
                p1 = segment[0];
                p2 = segment[1];
                // A zero-length segment is a degenerate rectangle. paper.js still
                // rasterizes it as a speck that survives some zoom levels.
                if (Number(p1[0]) === Number(p2[0]) && Number(p1[1]) === Number(p2[1])) {
                    continue;
                }
                startpoint = new paper.Point(p1[0], p1[1]);
                endpoint = new paper.Point(p2[0], p2[1]);
                const startKey = this.__pointKey(p1);
                const endKey = this.__pointKey(p2);
                // Rounded: stadium caps at terminals and corners.
                const startCap = capAt.has(startKey);
                const endCap = capAt.has(endKey);
                this.__drawStraightConnection(
                    connectionpath,
                    startpoint,
                    endpoint,
                    channelWidth,
                    true,
                    startCap,
                    endCap
                );
            }

            // Rounded stadiums add a circle at every endpoint. A 90° outer
            // corner is also filled square so the joint stays sharp. Other
            // angles keep only the circle — an axis-aligned square there
            // sticks out past the walls.
            this.__fillSquareChannelCorners(connectionpath, segments, channelWidth);
        }
        connectionpath.fillRule = "nonzero";
        connectionpath.fillColor = color;
        return connectionpath;
    }

    __pointKey(p: [number, number] | number[]): string {
        return `${Math.round(Number(p[0]))},${Math.round(Number(p[1]))}`;
    }

    /**
     * Round caps belong at true terminals and at touching corners. Valve-gap
     * ends are extra vertices that do not match the original wayPoints and do
     * not coincide with another segment — those stay square so the FLOW
     * channel is interrupted at the valve gap instead of the stadium caps
     * filling it.
     */
    __roundedCapLookup(
        segments: Array<[[number, number], [number, number]]>,
        wayPoints: Array<[number, number]> | undefined
    ): Set<string> {
        const capAt = new Set<string>();
        if (Array.isArray(wayPoints)) {
            for (const wp of wayPoints) {
                if (wp && wp.length >= 2) {
                    capAt.add(this.__pointKey(wp));
                }
            }
        }
        const counts = new Map<string, number>();
        for (const segment of segments) {
            if (!segment || segment.length < 2) {
                continue;
            }
            for (const pt of [segment[0], segment[1]]) {
                if (!pt || pt.length < 2) {
                    continue;
                }
                const key = this.__pointKey(pt);
                counts.set(key, (counts.get(key) || 0) + 1);
            }
        }
        counts.forEach((count, key) => {
            if (count > 1) {
                capAt.add(key);
            }
        });
        return capAt;
    }

    __drawSquareChannelRuns(
        compoundpath: paper.CompoundPath,
        segments: Array<[[number, number], [number, number]]>,
        channelWidth: number
    ): void {
        const runs = contiguousCenterlines(segments);
        for (const run of runs) {
            const outline = squareChannelOutline(run, channelWidth);
            if (outline.length < 3) {
                continue;
            }
            const path = new paper.Path();
            for (const point of outline) {
                path.add(new paper.Point(point[0], point[1]));
            }
            path.closed = true;
            compoundpath.addChild(path);
        }
    }

    __fillSquareChannelCorners(
        compoundpath: paper.CompoundPath,
        segments: Array<[[number, number], [number, number]]>,
        channelWidth: number
    ): void {
        if (!Array.isArray(segments) || segments.length < 2 || !channelWidth) {
            return;
        }
        const radius = channelWidth / 2;
        const nonzero: Array<[[number, number], [number, number]]> = [];
        for (const segment of segments) {
            if (!segment || segment.length < 2) {
                continue;
            }
            const a = segment[0];
            const b = segment[1];
            if (!a || !b || a.length < 2 || b.length < 2) {
                continue;
            }
            if (a[0] === b[0] && a[1] === b[1]) {
                continue;
            }
            nonzero.push(segment);
        }
        for (let i = 1; i < nonzero.length; i++) {
            const prev = nonzero[i - 1];
            const next = nonzero[i];
            if (Math.hypot(prev[1][0] - next[0][0], prev[1][1] - next[0][1]) > 0.5) {
                continue;
            }
            const d0x = prev[1][0] - prev[0][0];
            const d0y = prev[1][1] - prev[0][1];
            const d1x = next[1][0] - next[0][0];
            const d1y = next[1][1] - next[0][1];
            const len0 = Math.hypot(d0x, d0y);
            const len1 = Math.hypot(d1x, d1y);
            if (len0 < 1e-6 || len1 < 1e-6) {
                continue;
            }
            const deflection = Math.atan2(d0x * d1y - d0y * d1x, d0x * d1x + d0y * d1y);
            // Only a right angle. A square at a shallow bend is the nub
            // that sticks out past the channel wall.
            if (Math.abs(Math.abs(deflection) - Math.PI / 2) > (8 * Math.PI) / 180) {
                continue;
            }
            const joint = next[0];
            compoundpath.addChild(
                new paper.Path.Rectangle({
                    point: [joint[0] - radius, joint[1] - radius],
                    size: [channelWidth, channelWidth]
                })
            );
        }
    }

    __drawStraightConnection(
        compoundpath: paper.CompoundPath,
        startpoint: paper.Point,
        endpoint: paper.Point,
        channelWidth: number,
        roundedProfile: boolean,
        capStart = true,
        capEnd = true
    ): void  {
        const vec = endpoint.subtract(startpoint);
        const radius = channelWidth / 2;
        const length = vec.length;

        // Rounded profile is a center rectangle that ends on the connection
        // endpoints, plus circular caps at terminals / corners. Valve-gap ends
        // stay square so the FLOW channel is broken at the valve, not filled.
        if (roundedProfile) {
            if (length > 0) {
                const rec = new paper.Path.Rectangle({
                    point: startpoint,
                    size: [length, channelWidth]
                });
                rec.translate(([0, -radius] as unknown) as paper.Point);
                rec.rotate(vec.angle, startpoint);
                compoundpath.addChild(rec);
            }
            if (capStart) {
                compoundpath.addChild(new paper.Path.Circle(startpoint, radius));
            }
            if (capEnd) {
                compoundpath.addChild(new paper.Path.Circle(endpoint, radius));
            }
            return;
        }

        const rec = new paper.Path.Rectangle({
            point: startpoint,
            size: [length, channelWidth]
        });
        rec.translate(([0, -radius] as unknown) as paper.Point);
        rec.rotate(vec.angle, startpoint);
        compoundpath.addChild(rec);
        // Square profile: the rectangle already stops on the centerline at each
        // endpoint (flat end face). Do **not** add a separate cw×cw tip-square
        // centred on the terminal — that painted a half-width nub past every
        // PORT/MIXER landing and showed up as extra selectable "segments" when
        // the channel was double-clicked. Mixer incomplete-end tip-squares are
        // drawn by the mixer glyph itself (edgeBend / end-pipe), not here.
        // ``capStart`` / ``capEnd`` are only used for the rounded stadium path.
        void capStart;
        void capEnd;
    }

    render2DTarget(key: string | null, params: { [k: string]: any }) {
        const thickness = params.channelWidth / 5;
        const length = params.channelWidth;
        const x = params.position[0];
        const y = params.position[1];
        const color = params.color;
        let chair = new paper.Path.Rectangle(new paper.Rectangle(x - length / 2, y - thickness / 2, length, thickness));
        let chairtarget = chair.unite(new paper.Path.Rectangle(new paper.Rectangle(x - thickness / 2, y - length / 2, thickness, length)));
        chairtarget.fillColor = color;
        chairtarget.fillColor!.alpha = 0.5;
        return chairtarget;
    }
}
